    fn durable_prepublication_resume() -> GithubJobResumeV1 {
        let mut resume = durable_resume_with_run();
        resume.dispatch_commit = None;
        resume.run = None;
        resume.state = JobState::Created;
        resume.events.clear();
        resume
    }

